# Generated by scripts/sync_emojis.py from the images in hoyo-buddy-assets/assets/emojis
_EMOJI_IDS: dict[str, str] = json.loads(
    (pathlib.Path(__file__).parent / "emoji_ids.json").read_text(encoding="utf-8")
).get(CONFIG.env, {})


def _emoji(name: str) -> str:
    try:
        return _EMOJI_IDS[name]
    except KeyError:
        msg = f"Emoji {name!r} is not synced for env {CONFIG.env!r}, run scripts/sync_emojis.py"
        raise KeyError(msg) from None


